/*!
 * marked.min.js — Skills & Prompts Explorer
 *
 * NOTE: This is NOT the npm `marked` package. It is a tiny, self-contained,
 * in-house Markdown -> HTML renderer authored for this Explorer so the page has
 * ZERO third-party / network dependencies. It is the single vendored asset
 * referenced by the deliverable spec, kept under docs/explorer/ only.
 *
 * Supports: headings, bold/italic/inline-code, fenced & indented code, ordered &
 * unordered lists, blockquotes, horizontal rules, GFM tables, links, and
 * paragraphs. Output is escaped before inline formatting, so it is safe to feed
 * untrusted file contents. MIT-style: do what you like with it.
 */
(function (global) {
  "use strict";

  function esc(s) {
    return s
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  // Inline: protect code spans and links first (their content is not further
  // formatted), then run emphasis over whole text segments so **bold**/_em_ that
  // span multiple words render correctly.
  function inline(text) {
    var out = "";
    var i = 0;
    while (i < text.length) {
      var ch = text[i];
      // inline code span
      if (ch === "`") {
        var end = text.indexOf("`", i + 1);
        if (end !== -1) {
          out += "<code>" + esc(text.slice(i + 1, end)) + "</code>";
          i = end + 1;
          continue;
        }
      }
      // link [text](href)
      if (ch === "[") {
        var link = /^\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/.exec(text.slice(i));
        if (link) {
          var href = link[2];
          var safe = /^(https?:|mailto:|#|\.|\/)/.test(href) ? href : "#";
          out += '<a href="' + esc(safe) + '" rel="noopener">' + emphasis(esc(link[1])) + "</a>";
          i += link[0].length;
          continue;
        }
      }
      // plain run up to the next code span or link start
      var rest = text.slice(i);
      var next = rest.search(/`|\[[^\]]*\]\(/);
      if (next === -1) { out += emphasis(esc(rest)); break; }
      if (next === 0) { out += emphasis(esc(ch)); i += 1; continue; }
      out += emphasis(esc(rest.slice(0, next)));
      i += next;
    }
    return out;
  }

  function emphasis(s) {
    return s
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      .replace(/__([^_]+)__/g, "<strong>$1</strong>")
      .replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>")
      .replace(/(^|[^_])_([^_\n]+)_/g, "$1<em>$2</em>");
  }

  function parse(src) {
    src = String(src == null ? "" : src).replace(/\r\n?/g, "\n");
    var lines = src.split("\n");
    var html = [];
    var i = 0;

    function tableAt(start) {
      var head = lines[start];
      var sep = lines[start + 1] || "";
      if (head.indexOf("|") === -1) return null;
      if (!/^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$/.test(sep)) return null;
      var rows = [];
      var j = start;
      while (j < lines.length && lines[j].indexOf("|") !== -1 && lines[j].trim() !== "") {
        rows.push(lines[j]);
        j++;
      }
      return { rows: rows, end: j };
    }

    function cells(row) {
      var r = row.trim().replace(/^\|/, "").replace(/\|$/, "");
      return r.split("|").map(function (c) { return c.trim(); });
    }

    while (i < lines.length) {
      var line = lines[i];

      if (line.trim() === "") { i++; continue; }

      // fenced code
      var fence = /^(```|~~~)(.*)$/.exec(line);
      if (fence) {
        var buf = [];
        i++;
        while (i < lines.length && !new RegExp("^" + fence[1]).test(lines[i])) {
          buf.push(lines[i]); i++;
        }
        i++; // closing fence
        html.push('<pre class="md-pre"><code>' + esc(buf.join("\n")) + "</code></pre>");
        continue;
      }

      // heading
      var h = /^(#{1,6})\s+(.*)$/.exec(line);
      if (h) {
        var lvl = h[1].length;
        html.push("<h" + lvl + ">" + inline(h[2].trim()) + "</h" + lvl + ">");
        i++; continue;
      }

      // hr
      if (/^\s*([-*_])(\s*\1){2,}\s*$/.test(line)) { html.push("<hr/>"); i++; continue; }

      // table
      var tbl = tableAt(i);
      if (tbl) {
        var out = '<div class="md-tablewrap"><table class="md-table"><thead><tr>';
        cells(tbl.rows[0]).forEach(function (c) { out += "<th>" + inline(c) + "</th>"; });
        out += "</tr></thead><tbody>";
        for (var r = 2; r < tbl.rows.length; r++) {
          out += "<tr>";
          cells(tbl.rows[r]).forEach(function (c) { out += "<td>" + inline(c) + "</td>"; });
          out += "</tr>";
        }
        out += "</tbody></table></div>";
        html.push(out);
        i = tbl.end; continue;
      }

      // blockquote
      if (/^\s*>/.test(line)) {
        var qbuf = [];
        while (i < lines.length && /^\s*>/.test(lines[i])) {
          qbuf.push(lines[i].replace(/^\s*>\s?/, "")); i++;
        }
        html.push("<blockquote>" + parse(qbuf.join("\n")) + "</blockquote>");
        continue;
      }

      // lists (collect a run, support nesting by indent)
      if (/^\s*([-*+]|\d+\.)\s+/.test(line)) {
        var lbuf = [];
        while (i < lines.length && (lines[i].trim() === "" ? false : /^\s*([-*+]|\d+\.)\s+/.test(lines[i]) || /^\s{2,}\S/.test(lines[i]))) {
          lbuf.push(lines[i]); i++;
        }
        html.push(renderList(lbuf));
        continue;
      }

      // paragraph (gather until blank)
      var pbuf = [];
      while (i < lines.length && lines[i].trim() !== "" &&
             !/^(#{1,6})\s/.test(lines[i]) && !/^(```|~~~)/.test(lines[i]) &&
             !/^\s*([-*+]|\d+\.)\s+/.test(lines[i]) && !/^\s*>/.test(lines[i])) {
        pbuf.push(lines[i]); i++;
      }
      html.push("<p>" + inline(pbuf.join(" ").trim()) + "</p>");
    }
    return html.join("\n");

    function renderList(buf) {
      var ordered = /^\s*\d+\.\s+/.test(buf[0]);
      var tag = ordered ? "ol" : "ul";
      var items = [];
      var cur = null;
      buf.forEach(function (ln) {
        var m = /^\s*([-*+]|\d+\.)\s+(.*)$/.exec(ln);
        if (m) {
          if (cur !== null) items.push(cur);
          cur = m[2];
        } else if (cur !== null) {
          cur += "\n" + ln.trim();
        }
      });
      if (cur !== null) items.push(cur);
      return "<" + tag + ">" +
        items.map(function (it) { return "<li>" + inline(it) + "</li>"; }).join("") +
        "</" + tag + ">";
    }
  }

  var marked = function (src) { return parse(src); };
  marked.parse = parse;
  global.marked = marked;
})(typeof window !== "undefined" ? window : this);
